from lib import *
S = SS('t15')
steps = [
    step("消费者在处理途中被 kill -9:300 条消息,处理到第 100 条时杀掉消费者进程,再起一个新消费者把队列处理完。先处理、再 ack(至少一次):被杀时队列里 ready 200、unacked 0(没确认的第 100 条回到了队列),最后 300 条都处理了,但第 100 条被处理了 2 次。先 ack、再处理(至多一次):被杀时 ready 199,处理过的不同消息只有 299 条,第 100 条丢了。auto-ack(broker 一发出去就算成功):被杀时队列 ready 0——broker 已经把消息全推给了这个消费者,只处理了 101 条,丢了 101 到 299 共 199 条。三种确认方式对应三种结局:重复、丢一条、丢一大片。", t=tl(S(1)), mark=lidx(S(1), '先处理、再 ack', 'auto-ack'), done=lidx(S(1), '先 ack、再处理'), b=bars([['先处理再 ack:被处理多次的消息数', 1, '1'], ['先 ack 再处理:丢失的消息数', 1, '1'], ['auto-ack:丢失的消息数', 199, '199']], 200, mark=[0, 1], done=[2]), kv=KV([['先处理再 ack', '重复 1 条(第 100 条)'], ['先 ack 再处理', '丢 1 条'], ['auto-ack', '丢 199 条']], ['auto-ack'])),
    step("乱序:RabbitMQ 的队列是先进先出,但“处理完成的顺序”不一定等于发布顺序。(a) 单个消费者、prefetch=1,第 10 条被 nack 并重新入队一次:处理顺序 8、9、10、11、12、13,乱序 0 条——重新入队的消息回到原来的位置。(b) 两个消费者竞争同一个队列(一个每条 20 ms、一个每条 1 ms),200 条:处理完成的前 20 个是 0、2、3、……、16、1、17、19、20,第 1 条被慢消费者拿着,排在第 2 到第 16 条之后才完成,乱序的消息共 12 条。(c) 两个消费者(每条 5 ms),其中一个拿到第 50 条后卡了 100 ms 才 nack 重新入队:第 50 条是第 67 个处理完的,排在它前面处理完的编号比 50 大的有 16 条(最大到 66),乱序共 28 条。顺序在“多个消费者并行”和“处理失败后重新处理”时被打乱,队列本身没有错。", t=tl(S(2)), mark=lidx(S(2), '(b) 两个消费者竞争', '(c) 两个消费者'), done=lidx(S(2), '(a) 单个消费者'), b=bars([['(a) 单消费者 requeue:乱序', 0, '0'], ['(b) 两个消费者快慢不同:乱序', 12, '12'], ['(c) 一个消费者卡住再 nack:乱序', 28, '28']], 30, done=[0], mark=[1, 2]), kv=KV([['单消费者', '重新入队回到原位,不乱序'], ['多消费者', '快的先完成,乱序'], ['卡住再重投', '中间的消息已被处理完']], ['多消费者'])),
    step("Kafka 只有同一个分区内才有顺序。3 个分区、20 个实体、每个实体 100 条递增更新(共 2000 条,发布时各实体交错)。按实体 id 做 key:每个实体平均只落在 1.0 个分区,同一实体内顺序被打乱的实体数 0,实体内乱序的消息 0 条;但相对发布顺序整体有 1499 条是乱序的——不同实体分在不同分区,跨分区没有顺序可言。不设 key(这里给每条消息随机指定一个分区,效果等同随机分区):每个实体平均分布在 3.0 个分区,20 个实体全部在实体内被打乱,实体内乱序的消息有 1322 条。要让“同一实体的更新有序”,就得用实体 id 做 key。", t=tl(S(3)), mark=lidx(S(3), '不设 key(随机分区)'), done=lidx(S(3), '按实体 id 做 key'), b=bars([['按 key:实体内乱序的消息', 0, '0'], ['不设 key:实体内乱序的消息', 1322, '1322'], ['按 key:相对发布顺序乱序', 1499, '1499']], 1500, done=[0], mark=[1], cur=[2]), kv=KV([['按实体 id 做 key', '实体内有序,实体之间无序'], ['不设 key', '同一实体撒到 3 个分区,实体内也乱'], ['全局顺序', 'Kafka 不提供']], ['按实体 id 做 key'])),
    step("消费端的对策之一:消息带版本号(同一实体单调递增),处理时只接受更新的版本(UPDATE ... WHERE version < ?)。测试流:100 个实体、每个实体 20 条更新;每条消息有两部分,SET 类(把 status 设成 S<版本>)和累加类(counter 加 1);每 300 条之内随机重排(相邻 3 个版本的消息混在一起),再随机插入 200 条(10%)重复,共 2200 条;正确终态每个实体 status = S20、counter = 20。朴素的“来一条改一条”:58 个实体的 status 最终不是 S20,92 个实体的 counter 不是 20。只用版本号:status 0 个错(旧版本晚到被 WHERE 拒绝),counter 仍有 92 个错——累加类不是“谁新谁覆盖”,重复消息每来一次就多加一次,版本号管不了。", t=tl(S(4)), mark=lidx(S(4), '朴素:来一条改一条'), done=lidx(S(4), '只用版本号'), b=bars([['朴素:status 错的实体', 58, '58 / 100'], ['朴素:counter 错的实体', 92, '92 / 100'], ['只用版本号:status 错的实体', 0, '0 / 100'], ['只用版本号:counter 错的实体', 92, '92 / 100']], 100, mark=[0, 1, 3], done=[2]), kv=KV([['版本号', '挡住乱序,SET 类字段全对'], ['累加类字段', '重复消息会多加'], ['结论', 'SET 用版本号,累加要去重']], ['结论'])),
    step("乱序和重复同时来,四种消费端:朴素 status 错 58 个、counter 错 92 个;只做去重(seen 表,第 14 篇的做法)status 错 55 个、counter 错 0 个;只用版本号 status 错 0 个、counter 错 92 个;去重加版本号两项都是 0。去重解决重复(累加类字段对了),版本号解决乱序(SET 类字段对了),两种语义的字段各用各的办法,一起用才同时对。", t=tl(S(5)), mark=lidx(S(5), '只做去重', '只用版本号'), done=lidx(S(5), '去重 + 版本号'), b=bars([['只去重:status 错', 55, '55'], ['只版本号:counter 错', 92, '92'], ['去重 + 版本号:status 错', 0, '0'], ['去重 + 版本号:counter 错', 0, '0']], 100, mark=[0, 1], done=[2, 3]), kv=KV([['只去重', 'counter 对,status 55 个错'], ['只版本号', 'status 对,counter 92 个错'], ['两个一起', '0 个错']], ['两个一起'])),
]
A = mkartt('t15', 15, '分布式事务,消息重复,消息乱序,RabbitMQ,Kafka,版本号,去重,MySQL,真实验证,动画演示',
    '实测消费端怎么处理重复和乱序:RabbitMQ 先处理再 ack 重复 1 条、先 ack 再处理丢 1 条、auto-ack 丢 199 条;两个消费者快慢不同乱序 12 条;Kafka 按实体做 key 实体内 0 条乱序、不设 key 1322 条;版本号解决乱序(status 错 58 到 0)、去重解决重复(counter 错 92 到 0),合用才全对。',
    '消息队列通常只保证“至少一次”,重复和乱序是常态。这篇用真实的 RabbitMQ 和 Kafka,把消费者崩溃时三种确认方式的后果、多消费者与重新入队造成的乱序、分区与 key 对顺序的影响量出来,再试版本号和去重两种消费端对策。',
    [('1 / 1 / 199', 'kill -9 消费者后,先处理再 ack 的重复条数 / 先 ack 再处理丢的条数 / auto-ack 丢的条数(共 300 条)'), ('1322', 'Kafka 不设 key 时,2000 条里实体内被打乱的消息数(按实体 id 做 key 是 0)'), ('58 → 0,92 → 0', '朴素消费端 status 错的实体数与 counter 错的实体数,去重加版本号后都变成 0(100 个实体)')],
    [('重复与丢失', '<p>先处理再 ack 保证不丢,崩溃会重复;先 ack 再处理崩溃会丢;auto-ack 把一大批已推送的消息一起丢掉。</p>'),
     ('乱序的来源', '<p>队列本身先进先出,乱序来自多个消费者并行(快慢不同)和处理失败后重新处理;单消费者的重新入队不乱序。</p>'),
     ('Kafka 的顺序', '<p>只有同一个分区内有序。按实体 id 做 key,同一实体进同一分区,实体内有序;不设 key 则实体内也乱。</p>'),
     ('版本号', '<p>SET 类字段带上单调递增的版本号,处理时 WHERE version < ? 拒绝旧版本,乱序就不会覆盖新状态。</p>'),
     ('版本号 + 去重', '<p>累加类字段靠去重(每条消息只算一次),SET 类靠版本号,两者一起才同时对。</p>')],
    steps,
    [ENV_T + '。本篇用 RabbitMQ 4.3.6(pika 1.4.4,消费者是可以被 kill -9 的子进程)、Kafka 4.3.1 单节点 3 分区(confluent-kafka 2.16;不设 key 的情形由我给每条消息随机指定分区)、MySQL 26.7.0;乱序重排和重复是用固定种子的随机数在测试流里造的,重排窗口 300 条、重复 10% 是我设的',
     '没有验证:Kafka 生产者重试在 max.in.flight 大于 1 且未开幂等时造成的乱序;RabbitMQ 的 quorum 队列、single active consumer 对顺序的保证;消费者组再平衡时的重复(只测了 RabbitMQ 的崩溃重投);Kafka 事务 / exactly-once 语义;真实业务里版本号怎么生成(这里是现成的)'],
    '重复与乱序')
